cat > "$d/ZzEval.kt" <<'EOF'
import java.lang.management.ManagementFactory
import toporders.Order
import toporders.topIds

private fun zzBase(orders: List<Order>, limit: Int): List<Long> = orders.filter { it.total > 100 }.map { it.id }.take(limit)

private fun outcome(f: (List<Order>, Int) -> List<Long>, orders: List<Order>, limit: Int): String =
    try { f(orders, limit).toString() } catch (e: Exception) { e.javaClass.name }

private var sink = 0L

private fun bytesPerCall(f: (List<Order>, Int) -> List<Long>, orders: List<Order>): Long {
    val mx = ManagementFactory.getThreadMXBean() as com.sun.management.ThreadMXBean
    repeat(300) { sink += f(orders, 20).size }
    val before = mx.currentThreadAllocatedBytes
    repeat(200) { sink += f(orders, 20).size }
    return (mx.currentThreadAllocatedBytes - before) / 200
}

fun main(args: Array<String>) {
    if (args[0] == "equiv") {
        val mixed = List(500) { i -> Order(i * 1000L - 7, (i * 53) % 300) }
        val inputs = listOf(emptyList(), listOf(Order(1, 100)), listOf(Order(1, 101)), mixed,
            listOf(Order(Long.MIN_VALUE, Int.MAX_VALUE), Order(Long.MAX_VALUE, 101), Order(5, Int.MIN_VALUE)))
        var bad = 0
        for (orders in inputs) for (limit in listOf(-1, 0, 1, 2, 20, 10_000)) {
            val want = outcome(::zzBase, orders, limit)
            val got = outcome(::topIds, orders, limit)
            if (want != got) { bad++; println("MISMATCH size=${orders.size} limit=$limit: got $got, want $want") }
        }
        println("equivalence mismatches=$bad")
        kotlin.system.exitProcess(if (bad == 0) 0 else 1)
    }
    val orders = List(200_000) { i -> Order(1_000_000L + i, (i * 37) % 250) }
    val b = bytesPerCall(::zzBase, orders)
    val c = bytesPerCall(::topIds, orders)
    println("bytes per topIds(orders, 20) on 200000 orders: baseline $b, candidate $c")
    kotlin.system.exitProcess(if (c * 20 <= b) 0 else 1)
}
EOF
kotlinc "$d/src" "$d/ZzEval.kt" -include-runtime -d "$d/eval.jar" > "$d/kc.log" 2>&1 || { grep -i error "$d/kc.log" | head -5; exit 1; }
